import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: basic rate limiting (in-memory, resets on restart)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// User search endpoint - supports flexible filtering
app.get('/api/v2/users/search', async (req, res) => {
  try {
    const { department, role, status, sort_by, order } = req.query;

    let query = 'SELECT id, username, email, department, role, status, created_at FROM users WHERE 1=1';
    const params = [];
    let paramIndex = 1;

    if (department) {
      params.push(department);
      query += ` AND department = $${paramIndex++}`;
    }

    if (role) {
      params.push(role);
      query += ` AND role = $${paramIndex++}`;
    }

    if (status) {
      params.push(status);
      query += ` AND status = $${paramIndex++}`;
    }

    // Sort support - validated against allowlist
    const allowedSorts = ['username', 'created_at', 'department', 'email'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortOrder = order === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortOrder} LIMIT 100`;

    const result = await pool.query(query, params);
    res.json({ users: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Admin analytics endpoint
app.get('/api/v2/admin/analytics', async (req, res) => {
  try {
    const { metric, group_by, date_from, date_to } = req.query;

    // Build analytics query dynamically
    const validMetrics = ['count', 'active_sessions', 'login_attempts'];
    if (!validMetrics.includes(metric)) {
      return res.status(400).json({ error: 'invalid metric' });
    }

    // group_by is used to allow flexible aggregation
    let query;
    if (metric === 'count') {
      query = `SELECT ${group_by}, COUNT(*) as total FROM users`;
    } else if (metric === 'active_sessions') {
      query = `SELECT ${group_by}, COUNT(*) as total FROM sessions WHERE active = true`;
    } else {
      query = `SELECT ${group_by}, COUNT(*) as total FROM login_attempts`;
    }

    const conditions = [];
    const params = [];
    let paramIndex = 1;

    if (date_from) {
      params.push(date_from);
      conditions.push(`created_at >= $${paramIndex++}`);
    }
    if (date_to) {
      params.push(date_to);
      conditions.push(`created_at <= $${paramIndex++}`);
    }

    if (conditions.length > 0) {
      query += ' WHERE ' + conditions.join(' AND ');
    }

    query += ` GROUP BY ${group_by}`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows });
  } catch (err) {
    console.error('Analytics error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', timestamp: new Date().toISOString() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
});
